 execute(admin,"CREATE TABLE orders(id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,external_key VARCHAR(40) NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL) ENGINE=InnoDB")
 for row in [(7,'early',Decimal('3.20')),(2147483646,'near',Decimal('17.75')),(2147483647,'ceiling',Decimal('99.99'))]:execute(admin,'INSERT INTO orders VALUES(%s,%s,%s)',row)
 before=execute(admin,'SELECT * FROM orders ORDER BY id')
 try:execute(admin,"INSERT INTO orders(external_key,amount) VALUES('baseline-fail',1.00)")
 except Exception as exc:
  assert exc.args[0] in [1467,1264] or (exc.args[0]==1062 and '2147483647' in str(exc) and 'PRIMARY' in str(exc)),exc
 else:raise AssertionError('fixture did not reproduce signed INT auto-increment exhaustion')
 client=learner('ALTER,SELECT,CREATE,INSERT')
 try:execute(client,pathlib.Path('migrate.sql').read_text(encoding='utf-8'))
