 assert execute(admin,'SELECT * FROM orders ORDER BY id')==before,'migration changed existing records'
 info=execute(admin,"SELECT DATA_TYPE,COLUMN_TYPE,IS_NULLABLE,EXTRA,COLUMN_KEY FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='training' AND TABLE_NAME='orders' AND COLUMN_NAME='id'")
 assert info==(('bigint','bigint','NO','auto_increment','PRI'),),info
